/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_Complaint_NoticeFiveNine_EventRecord_INSERT 
AFTER INSERT ON tbl_rera_complaint_sectionfivenine_eventaction 
FOR EACH ROW
BEGIN
   
    Declare v_SectionFiveNine_EventAction_ID BigInt; 
    Declare v_EventAction_Type BigInt;
	Declare v_EventAction_IdentifiedBy varchar(150);
	Declare v_EventAction_IdentifiedOn datetime(3); 
	Declare v_Related_NoticesSectionFiveNine_ID BigInt; 
    Declare v_Related_NoticeFile_NumberDetails varchar(150);
	Declare v_IsActiveValue int;
    Declare v_IsDraftValue int;
    Declare v_getIsPublicViewValue int;
    
    -- Assign Values
    SET v_SectionFiveNine_EventAction_ID=NEW.SectionFiveNine_EventAction_ID;
    SET v_EventAction_Type=NEW.EventAction_Type;
	SET v_EventAction_IdentifiedBy=NEW.EventAction_IdentifiedBy;
	SET v_EventAction_IdentifiedOn=NEW.EventAction_IdentifiedOn;
	SET v_Related_NoticesSectionFiveNine_ID=NEW.Related_NoticesSectionFiveNine_ID;
    SET v_Related_NoticeFile_NumberDetails=NEW.Related_NoticeFile_NumberDetails;
	SET v_IsActiveValue=NEW.IsActive;
    SET v_IsDraftValue=NEW.IsDraft;


-- Hearing Date Issued          
If v_EventAction_Type = 7832   
then 
   update tbl_rera_webapplication_noticessectionlockcodefivenine set IsPublicView=1 
   where NoticesSectionFiveNine_ID=v_Related_NoticesSectionFiveNine_ID and IsActive=1 and IsPublicView=0;
   
end if;

-- Merger File or Rejected          
If ((v_EventAction_Type = 7831) or (v_EventAction_Type = 7836))   
then      
   update tbl_rera_webapplication_noticessectionlockcodefivenine set IsPublicView=0 
   where NoticesSectionFiveNine_ID=v_Related_NoticesSectionFiveNine_ID and IsActive=1 and IsPublicView=1;
   
end if;

-- UnderPrcess or Proceedings          
If (v_EventAction_Type = 7837)   
then      
   update tbl_rera_webapplication_noticessectionlockcodefivenine set IsPublicView=0 
   where NoticesSectionFiveNine_ID=v_Related_NoticesSectionFiveNine_ID and IsActive=1 and IsPublicView=1;
   
end if;

-- Move to PublicView (vice versa)          
If (v_EventAction_Type = 7835)   
then 
   select IsPublicView into v_getIsPublicViewValue from tbl_rera_webapplication_noticessectionlockcodefivenine 
   where NoticesSectionFiveNine_ID=v_Related_NoticesSectionFiveNine_ID and IsActive=1 
